import { BRAND, FONT, SHADOW } from "@/lib/brand";
import { categoryLabels, type BlogContentBlock, type BlogPost } from "@/lib/data/blog-posts";

interface Props {
  post: BlogPost;
  related: BlogPost[];
}

function ContentBlock({ block }: { block: BlogContentBlock }) {
  switch (block.type) {
    case "p":
      return (
        <p
          style={{
            fontFamily: FONT.sans,
            fontSize: 17,
            lineHeight: 1.75,
            color: BRAND.stoneDark,
            marginBottom: 20,
          } as React.CSSProperties}
        >
          {block.text}
        </p>
      );
    case "h2":
      return (
        <h2
          style={{
            fontFamily: FONT.sans,
            fontSize: 26,
            fontWeight: 700,
            color: BRAND.onyx,
            letterSpacing: "-0.02em",
            marginTop: 40,
            marginBottom: 16,
          } as React.CSSProperties}
        >
          {block.text}
        </h2>
      );
    case "h3":
      return (
        <h3
          style={{
            fontFamily: FONT.sans,
            fontSize: 19,
            fontWeight: 700,
            color: BRAND.onyx,
            letterSpacing: "-0.015em",
            marginTop: 32,
            marginBottom: 12,
          } as React.CSSProperties}
        >
          {block.text}
        </h3>
      );
    case "ul":
      return (
        <ul style={{ paddingLeft: 22, marginBottom: 24 } as React.CSSProperties}>
          {block.items.map((item, i) => (
            <li
              key={i}
              style={{
                fontFamily: FONT.sans,
                fontSize: 16,
                lineHeight: 1.7,
                color: BRAND.stoneDark,
                marginBottom: 8,
              } as React.CSSProperties}
            >
              {item}
            </li>
          ))}
        </ul>
      );
    case "quote":
      return (
        <blockquote
          style={{
            borderLeft: `3px solid ${BRAND.rust}`,
            paddingLeft: 24,
            marginTop: 32,
            marginBottom: 32,
          } as React.CSSProperties}
        >
          <p
            style={{
              fontFamily: FONT.serif,
              fontSize: 24,
              fontStyle: "italic",
              lineHeight: 1.4,
              color: BRAND.onyx,
              marginBottom: block.attribution ? 12 : 0,
            } as React.CSSProperties}
          >
            &ldquo;{block.text}&rdquo;
          </p>
          {block.attribution && (
            <cite
              style={{
                fontFamily: FONT.sans,
                fontSize: 13,
                color: BRAND.stoneLight,
                fontStyle: "normal",
              } as React.CSSProperties}
            >
              — {block.attribution}
            </cite>
          )}
        </blockquote>
      );
    case "callout": {
      const bg =
        block.tone === "rust"
          ? BRAND.rustWash
          : block.tone === "amber"
          ? BRAND.amberWash
          : BRAND.sageWash;
      const border =
        block.tone === "rust"
          ? BRAND.rust
          : block.tone === "amber"
          ? BRAND.amber
          : BRAND.sage;
      return (
        <div
          style={{
            padding: 22,
            borderRadius: 14,
            background: bg,
            border: `1px solid ${border}30`,
            marginTop: 24,
            marginBottom: 24,
            fontFamily: FONT.sans,
            fontSize: 15,
            fontWeight: 500,
            lineHeight: 1.6,
            color: BRAND.onyx,
          } as React.CSSProperties}
        >
          {block.text}
        </div>
      );
    }
    case "code":
      return (
        <pre
          style={{
            padding: 20,
            borderRadius: 12,
            background: BRAND.onyx,
            color: BRAND.bone,
            fontFamily: FONT.mono,
            fontSize: 13,
            lineHeight: 1.6,
            overflow: "auto",
            marginTop: 16,
            marginBottom: 24,
          } as React.CSSProperties}
        >
          <code>{block.text}</code>
        </pre>
      );
  }
}

